patch_result.patch:
--- a/Zend/zend_execute.c
+++ b/Zend/zend_execute.c
@@ -3880,7 +3880,11 @@
 	zval *cv = EX_VAR_NUM(0);
 	int count = EX(func)->op_array.last_var;
 	while (EXPECTED(count != 0)) {
-		i_zval_ptr_dtor(cv);
+		/* Clear CV slot before running dtor to avoid re-entrant/double-dtor paths
+		 * through aliased CVs during exception unwinding. */
+		zval tmp = *cv;
+		ZVAL_UNDEF(cv);
+		i_zval_ptr_dtor_nogc(&tmp);
 		cv++;
 		count--;
 	}

